import requests
import time
import os
from datetime import datetime, timedelta

CACHE_FILE = "weather_cache.dat"

def load_cache():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, "r") as f:
            return {line.strip().split(":")[0].strip(): line.strip().split(":")[1].strip() for line in f}
    return {}

def save_cache(cache):
    with open(CACHE_FILE, "w") as f:
        for city, temp in cache.items():
            f.write(f"{city}: {temp}\n")

def get_temperature(city):
    cache = load_cache()
    current_time = datetime.now()
    cache_time = datetime.fromisoformat(cache[city].split(" ")[0]) if city in cache else None

    if city in cache and (current_time - cache_time).total_seconds() < 600:
        return cache[city].split(" ")[1]

    url = f"https://wttr.in/{city.replace(' ', '_')}?format=%t"
    try:
        response = requests.get(url)
        response.raise_for_status()
        temp = response.text.strip()
        cache[city] = f"{current_time.isoformat()} {temp}"
        return temp
    except requests.RequestException:
        return "N/A"

def main():
    cities = []
    while True:
        try:
            city = input().strip()
            if not city:
                break
            cities.append(city)
        except EOFError:
            break

    cache = load_cache()
    last_request_time = 0

    for city in cities:
        if city in cache and (datetime.now() - datetime.fromisoformat(cache[city].split(" ")[0])).total_seconds() < 600:
            print(f"{city}: {cache[city].split(' ')[1]}")
        else:
            temp = get_temperature(city)
            print(f"{city}: {temp}")
            if last_request_time + 1 < time.time():
                time.sleep(1 - (time.time() - last_request_time))
            last_request_time = time.time()

    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import time
import requests
from datetime import datetime, timedelta

def load_cache(filename):
    try:
        with open(filename, 'r') as f:
            return {line.strip().split(':')[0]: line.strip().split(':')[1:] for line in f}
    except FileNotFoundError:
        return {}

def save_cache(filename, cache):
    with open(filename, 'w') as f:
        for city, (timestamp, temp) in cache.items():
            f.write(f"{city}: {timestamp} {temp}\n")

def get_temperature_from_cache(cache, city):
    if city in cache:
        timestamp_str, temp = cache[city]
        timestamp = datetime.fromisoformat(timestamp_str)
        if datetime.now() - timestamp < timedelta(seconds=600):
            return temp
    return None

def update_cache(cache, city, temp):
    cache[city] = (datetime.now().isoformat(), temp)
    return cache

def fetch_temperature(city):
    url = f"https://wttr.in/{city.replace(' ', '_')}?format=%t"
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text.strip()
    except requests.RequestException:
        return None

def main():
    cache_file = "weather_cache.dat"
    cache = load_cache(cache_file)
    http_requests = 0
    last_request_time = 0

    for city in sys.stdin:
        city = city.strip()
        if not city:
            continue

        temp = get_temperature_from_cache(cache, city)
        if temp is not None:
            print(f"{city}: {temp}")
            continue

        temp = fetch_temperature(city)
        if temp is not None:
            http_requests += 1
            if http_requests > 1 and last_request_time + 1 < time.time():
                time.sleep(1)
            last_request_time = time.time()
            cache = update_cache(cache, city, temp)
            print(f"{city}: {temp}")
        else:
            print(f"{city}: (no data)")

    save_cache(cache_file, cache)

if __name__ == "__main__":
    main()

